class Solution {
public:
    int maxTrailingZeros(vector<vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        auto get_f = [](int x) -> pair<int, int> {
            int c2 = 0, c5 = 0;
            while (x > 0 && x % 2 == 0) { c2++; x /= 2; }
            while (x > 0 && x % 5 == 0) { c5++; x /= 5; }
            return {c2, c5};
        };

        vector<vector<pair<int, int>>> f(R, vector<pair<int, int>>(C));
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                f[r][c] = get_f(grid[r][c]);
            }
        }

        vector<vector<pair<int, int>>> row_pref(R, vector<pair<int, int>>(C + 1, {0, 0}));
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                row_pref[r][c + 1].first = row_pref[r][c].first + f[r][c].first;
                row_pref[r][c + 1].second = row_pref[r][c].second + f[r][c].second;
            }
        }

        vector<vector<pair<int, int>>> col_pref(R + 1, vector<pair<int, int>>(C, {0, 0}));
        for (int c = 0; c < C; c++) {
            for (int r = 0; r < R; r++) {
                col_pref[r + 1][c].first = col_pref[r][c].first + f[r][c].first;
                col_pref[r + 1][c].second = col_pref[r][c].second + f[r][c].second;
            }
        }

        int ans = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                auto [c2, c5] = f[r][c];
                int up2 = col_pref[r + 1][c].first, up5 = col_pref[r + 1][c].second;
                int dn2 = col_pref[R][c].first - col_pref[r][c].first, dn5 = col_pref[R][c].second - col_pref[r][c].second;
                int lt2 = row_pref[r][c + 1].first, lt5 = row_pref[r][c + 1].second;
                int rt2 = row_pref[r][C].first - row_pref[r][c].first, rt5 = row_pref[r][C].second - row_pref[r][c].second;

                ans = max(ans, min(up2 + lt2 - c2, up5 + lt5 - c5));
                ans = max(ans, min(up2 + rt2 - c2, up5 + rt5 - c5));
                ans = max(ans, min(dn2 + lt2 - c2, dn5 + lt5 - c5));
                ans = max(ans, min(dn2 + rt2 - c2, dn5 + rt5 - c5));
            }
        }
        return ans;
    }
};

class Solution {
    public int maxTrailingZeros(int[][] grid) {
        int R = grid.length, C = grid[0].length;
        int[][][] f = new int[R][C][2];
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int x = grid[r][c];
                while (x > 0 && x % 2 == 0) { f[r][c][0]++; x /= 2; }
                while (x > 0 && x % 5 == 0) { f[r][c][1]++; x /= 5; }
            }
        }

        int[][][] rowPref = new int[R][C + 1][2];
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                rowPref[r][c + 1][0] = rowPref[r][c][0] + f[r][c][0];
                rowPref[r][c + 1][1] = rowPref[r][c][1] + f[r][c][1];
            }
        }

        int[][][] colPref = new int[R + 1][C][2];
        for (int c = 0; c < C; c++) {
            for (int r = 0; r < R; r++) {
                colPref[r + 1][c][0] = colPref[r][c][0] + f[r][c][0];
                colPref[r + 1][c][1] = colPref[r][c][1] + f[r][c][1];
            }
        }

        int ans = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int c2 = f[r][c][0], c5 = f[r][c][1];
                int up2 = colPref[r + 1][c][0], up5 = colPref[r + 1][c][1];
                int dn2 = colPref[R][c][0] - colPref[r][c][0], dn5 = colPref[R][c][1] - colPref[r][c][1];
                int lt2 = rowPref[r][c + 1][0], lt5 = rowPref[r][c + 1][1];
                int rt2 = rowPref[r][C][0] - rowPref[r][c][0], rt5 = rowPref[r][C][1] - rowPref[r][c][1];

                ans = Math.max(ans, Math.min(up2 + lt2 - c2, up5 + lt5 - c5));
                ans = Math.max(ans, Math.min(up2 + rt2 - c2, up5 + rt5 - c5));
                ans = Math.max(ans, Math.min(dn2 + lt2 - c2, dn5 + lt5 - c5));
                ans = Math.max(ans, Math.min(dn2 + rt2 - c2, dn5 + rt5 - c5));
            }
        }
        return ans;
    }
}

