var maxTrailingZeros = function(grid) {
    const R = grid.length, C = grid[0].length;
    const f = Array.from({ length: R }, () => Array.from({ length: C }, () => [0, 0]));
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            let x = grid[r][c];
            let c2 = 0, c5 = 0;
            while (x > 0 && x % 2 === 0) { c2++; x /= 2; }
            while (x > 0 && x % 5 === 0) { c5++; x /= 5; }
            f[r][c] = [c2, c5];
        }
    }

    const rowPref = Array.from({ length: R }, () => Array.from({ length: C + 1 }, () => [0, 0]));
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            rowPref[r][c + 1][0] = rowPref[r][c][0] + f[r][c][0];
            rowPref[r][c + 1][1] = rowPref[r][c][1] + f[r][c][1];
        }
    }

    const colPref = Array.from({ length: R + 1 }, () => Array.from({ length: C }, () => [0, 0]));
    for (let c = 0; c < C; c++) {
        for (let r = 0; r < R; r++) {
            colPref[r + 1][c][0] = colPref[r][c][0] + f[r][c][0];
            colPref[r + 1][c][1] = colPref[r][c][1] + f[r][c][1];
        }
    }

    let ans = 0;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            const [c2, c5] = f[r][c];
            const up2 = colPref[r + 1][c][0], up5 = colPref[r + 1][c][1];
            const dn2 = colPref[R][c][0] - colPref[r][c][0], dn5 = colPref[R][c][1] - colPref[r][c][1];
            const lt2 = rowPref[r][c + 1][0], lt5 = rowPref[r][c + 1][1];
            const rt2 = rowPref[r][C][0] - rowPref[r][c][0], rt5 = rowPref[r][C][1] - rowPref[r][c][1];

            ans = Math.max(ans, Math.min(up2 + lt2 - c2, up5 + lt5 - c5));
            ans = Math.max(ans, Math.min(up2 + rt2 - c2, up5 + rt5 - c5));
            ans = Math.max(ans, Math.min(dn2 + lt2 - c2, dn5 + lt5 - c5));
            ans = Math.max(ans, Math.min(dn2 + rt2 - c2, dn5 + rt5 - c5));
        }
    }
    return ans;
